// TypeScript Version: 4.1

/**
* Computes the epsilon insensitive loss.
*
* @param e - insensitivity parameter
* @param y - true target value
* @param p - predicted value
* @returns epsilon insensitive loss
*
* @example
* var v = epsilonInsensitive( 5.0, 10.2, 0.782 );
* // returns 4.418
*
* @example
* var v = epsilonInsensitive( 2.0, 8.0, 0.202 );
* // returns 5.798
*
* @example
* var v = epsilonInsensitive( 1.0, 23.2, -0.999 );
* // returns 23.199
*
* @example
* var v = epsilonInsensitive( 11.0, -12.2, 0.234 );
* // returns ~1.434
*
* @example
* var v = epsilonInsensitive( 2.0, -21.0, 0.2 );
* // returns 19.2
*
* @example
* var v = epsilonInsensitive( 9.0, 4.0, -0.9 );
* // returns 0.0
*/
declare function epsilonInsensitive( e: number, y: number, p: number ): number;


// EXPORTS //

export = epsilonInsensitive;
